import h5py
import numpy as np

def _tostr(arr):
    a = np.array(arr).ravel()
    return ''.join(chr(int(c)) for c in a)

def conv(f, item):
    if isinstance(item, h5py.Group):
        cls = item.attrs.get('MATLAB_class', b'')
        out = {}
        for k in item.keys():
            out[k] = conv(f, item[k])
        return out
    elif isinstance(item, h5py.Dataset):
        cls = item.attrs.get('MATLAB_class', b'')
        if isinstance(cls, bytes):
            cls = cls.decode()
        if item.dtype == object:
            # cell array or struct array element refs
            arr = item[()]
            shape = arr.shape
            flat = arr.ravel()
            out = []
            for r in flat:
                try:
                    out.append(conv(f, f[r]))
                except Exception:
                    out.append(None)
            return np.array(out, dtype=object).reshape(shape)
        else:
            data = item[()]
            if cls == 'char':
                return _tostr(data)
            if cls == 'logical':
                return np.array(data).astype(bool).T
            return np.array(data).T
    return None

def loadmat73(fn):
    f = h5py.File(fn, 'r')
    out = {}
    for k in f.keys():
        if k == '#refs#':
            continue
        out[k] = conv(f, f[k])
    return out, f
