import re, os, glob

def parse_meta(dirpath='/app/code/DataLoadingScripts/Recording and video'):
    entries = []
    for fn in sorted(glob.glob(os.path.join(dirpath,'*.m'))):
        cur = None
        for line in open(fn):
            s = line.strip()
            if s.startswith('%'):
                continue
            m = re.search(r"meta\(end\+1\)", s)
            if m:
                if cur: entries.append(cur)
                cur = {'file': os.path.basename(fn)}
            m = re.search(r"\.anm\s*=\s*'([^']+)'", s)
            if m and cur is not None: cur['anm'] = m.group(1)
            m = re.search(r"\.date\s*=\s*'([^']+)'", s)
            if m and cur is not None: cur['date'] = m.group(1)
            m = re.search(r"\.probe\s*=\s*(\[[^\]]*\]|\d+)", s)
            if m and cur is not None:
                v = m.group(1)
                if v.startswith('['):
                    cur['probe'] = [int(x) for x in v.strip('[]').split()]
                else:
                    cur['probe'] = [int(v)]
        if cur: entries.append(cur); cur=None
    return entries

if __name__ == '__main__':
    e = parse_meta()
    for x in e:
        print(x)
    print(len(e))
