"""Fast readers for MATLAB v7.3 data objects from Economo lab dataset."""
import h5py
import numpy as np


def _str(f, ref_or_ds):
    ds = f[ref_or_ds] if isinstance(ref_or_ds, h5py.Reference) else ref_or_ds
    a = np.array(ds).ravel()
    try:
        return ''.join(chr(int(c)) for c in a)
    except Exception:
        return ''


def vec(f, ds):
    """numeric dataset -> 1d array"""
    return np.array(ds[()]).ravel()


class Session:
    def __init__(self, path):
        self.f = h5py.File(path, 'r')
        self.o = self.f['obj']

    def close(self):
        self.f.close()

    # ---------------- behavior ----------------
    @property
    def ntrials(self):
        return int(vec(self.f, self.o['bp']['Ntrials'])[0])

    def bp_flag(self, name):
        return vec(self.f, self.o['bp'][name]).astype(bool)

    def stim_enable(self):
        return vec(self.f, self.o['bp']['stim']['enable']).astype(bool)

    def ev(self, name):
        return vec(self.f, self.o['bp']['ev'][name])

    def lick_times(self, side):
        """list of arrays of lick times per trial; side in ('L','R')"""
        ds = self.o['bp']['ev']['lick' + side]
        out = []
        for r in np.array(ds[()]).ravel():
            try:
                d = self.f[r]
                a = np.array(d[()]).ravel().astype(float)
                if d.shape == (2,) and d.dtype == np.uint64:  # empty placeholder
                    a = np.array([])
            except Exception:
                a = np.array([])
            out.append(a)
        return out

    # ---------------- spikes ----------------
    def nprobes(self):
        return self.o['clu'].shape[0]

    def probe_group(self, prbnum):
        """prbnum is 1-indexed"""
        ref = self.o['clu'][prbnum - 1, 0]
        g = self.f[ref]
        if not isinstance(g, h5py.Group):
            return None
        return g

    def qualities(self, prbnum):
        g = self.probe_group(prbnum)
        if g is None:
            return []
        return [_str(self.f, r).strip() for r in np.array(g['quality'][()]).ravel()]

    def clu_spikes(self, prbnum, cluix):
        """return (trial, trialtm) arrays for cluster index cluix (0-indexed)"""
        g = self.probe_group(prbnum)
        trial = np.array(self.f[np.array(g['trial'][()]).ravel()[cluix]][()]).ravel().astype(int)
        trialtm = np.array(self.f[np.array(g['trialtm'][()]).ravel()[cluix]][()]).ravel().astype(float)
        return trial, trialtm

    def probe_locs(self):
        """location strings for each probe, '' if unavailable"""
        out = []
        try:
            loc = self.o['ex']['probe']['loc']
            for r in np.array(loc[()]).ravel():
                out.append(_str(self.f, r).strip())
        except Exception:
            pass
        return out

    # ---------------- video ----------------
    def has_traj(self):
        return 'traj' in self.o

    def traj_featnames(self, view):
        """view 0 = side cam, 1 = bottom cam"""
        t = self.f[self.o['traj'][view, 0]]
        r0 = np.array(t['featNames'][()]).ravel()[0]
        ds = self.f[r0]
        names = [_str(self.f, r) for r in np.array(ds[()]).ravel()]
        return names

    def traj_trial(self, view, trial):
        """return (frameTimes, ts) for trial (0-indexed); ts shape (nframes,3,nfeat)"""
        t = self.f[self.o['traj'][view, 0]]
        try:
            ftr = np.array(t['frameTimes'][()]).ravel()[trial]
            ft = np.array(self.f[ftr][()]).ravel().astype(float)
        except Exception:
            ft = None
        try:
            tsr = np.array(t['ts'][()]).ravel()[trial]
            ts = np.array(self.f[tsr][()]).astype(float)
            ts = ts.T  # matlab (frames,3,feat) stored transposed
        except Exception:
            ts = None
        return ft, ts

    def ndropped(self, view):
        t = self.f[self.o['traj'][view, 0]]
        if 'NdroppedFrames' not in t:
            return None
        out = []
        for r in np.array(t['NdroppedFrames'][()]).ravel():
            try:
                out.append(float(np.array(self.f[r][()]).ravel()[0]))
            except Exception:
                out.append(np.nan)
        return np.array(out)

    def video_offset(self):
        """vidshift = mode(sglx.bitcode.bitstart)/fs - mode(bp.ev.bitStart)"""
        from scipy import stats
        bs = vec(self.f, self.o['sglx']['bitcode']['bitstart'])
        fs = vec(self.f, self.o['sglx']['fs'])[0]
        bitStart = self.ev('bitStart')
        m1 = stats.mode(bs, keepdims=False).mode / fs
        m2 = stats.mode(bitStart, keepdims=False).mode
        return float(m1 - m2)
